pub fn body_status(
    declared: Option<usize>,
    actual: usize,
    maximum: usize,
) -> u16 {
    if actual > maximum || declared.is_some_and(|n| n > maximum) {
        413
    } else if declared.is_some_and(|n| n != actual) {
        400
    } else {
        200
    }
}

fn main() {
    assert_eq!(body_status(Some(5), 5, 10), 200, "case 1");
    assert_eq!(body_status(Some(0), 0, 0), 200, "case 2");
    assert_eq!(body_status(Some(20), 0, 10), 413, "case 3");
    assert_eq!(body_status(Some(5), 4, 10), 400, "case 4");
    assert_eq!(body_status(None, 11, 10), 413, "case 5");
    assert_eq!(body_status(None, 5, 10), 200, "case 6");
    println!("worked example passed");
}

